using System;using System.Collections.Generic;using System.Diagnostics;using System.Drawing;using System.IO;using System.Linq;using System.Reflection;using System.Runtime.InteropServices;using System.Threading;using System.Threading.Tasks;using System.Windows.Forms;using SlopProX;
class V8GuiTests {
 static BindingFlags F=BindingFlags.Public|BindingFlags.NonPublic|BindingFlags.Instance;static List<string> lines=new List<string>();static List<Exception> errors=new List<Exception>();static int failures;static string root;
 static object Field(object o,string n){for(Type t=o.GetType();t!=null;t=t.BaseType){var f=t.GetField(n,F|BindingFlags.DeclaredOnly);if(f!=null)return f.GetValue(o);}throw new Exception(n);}static void Set(object o,string n,object v){o.GetType().GetField(n,F).SetValue(o,v);}static object Call(object o,string n,params object[] a){for(Type t=o.GetType();t!=null;t=t.BaseType){var method=t.GetMethods(F|BindingFlags.DeclaredOnly).FirstOrDefault(m=>m.Name==n&&m.GetParameters().Length==a.Length);if(method!=null)return method.Invoke(o,a);}throw new Exception(n);}
 static void Check(bool b,string why){if(!b)throw new Exception(why);}static void Test(string name,Action body){int before=errors.Count;try{body();Pump(20);Check(before==errors.Count,"UI exception "+(errors.Count>before?errors.Last().ToString():""));lines.Add("PASS "+name);}catch(Exception e){failures++;lines.Add("FAIL "+name+" :: "+e);}File.WriteAllLines(Path.Combine(root,"gui.txt"),lines);}
 [DllImport("user32.dll")]static extern IntPtr SendMessage(IntPtr h,int m,IntPtr w,IntPtr l);[DllImport("user32.dll")]static extern bool PrintWindow(IntPtr h,IntPtr dc,uint flags);[DllImport("user32.dll")]static extern bool SetKeyboardState(byte[] b);[DllImport("user32.dll")]static extern bool GetKeyboardState(byte[] b);[DllImport("user32.dll")]static extern bool SetProcessDpiAwarenessContext(IntPtr c);
 static void Pump(int ms){var sw=Stopwatch.StartNew();while(sw.ElapsedMilliseconds<ms){Application.DoEvents();Thread.Sleep(3);}}
 static void Mouse(Control c,int id,double x,double y,int buttons=0){float s=DisplayScale.For(c);int ix=(int)(x*s),iy=(int)(y*s);SendMessage(c.Handle,id,(IntPtr)buttons,(IntPtr)((iy<<16)|(ix&65535)));}
 static void Mods(Keys mods,Action action){var old=new byte[256];GetKeyboardState(old);var state=(byte[])old.Clone();state[16]=(mods&Keys.Shift)!=0?(byte)128:(byte)0;state[17]=(mods&Keys.Control)!=0?(byte)128:(byte)0;state[18]=(mods&Keys.Alt)!=0?(byte)128:(byte)0;SetKeyboardState(state);try{action();}finally{SetKeyboardState(old);}}
 static void Click(Control c,double x,double y,Keys mods=Keys.None){Mods(mods,()=>{Mouse(c,0x201,x,y,1);Mouse(c,0x202,x,y);});Pump(20);}
 static void Drag(Control c,double x,double y,double endX,double endY,Keys mods=Keys.None){Mods(mods,()=>{Mouse(c,0x201,x,y,1);Mouse(c,0x200,endX,endY,1);Mouse(c,0x202,endX,endY);});Pump(30);}
 static void Screenshot(Form f,string name){Pump(70);using(var image=new Bitmap(f.Width,f.Height)){using(var g=Graphics.FromImage(image)){IntPtr dc=g.GetHdc();try{Check(PrintWindow(f.Handle,dc,2),"Own window capture failed");}finally{g.ReleaseHdc(dc);}}image.Save(Path.Combine(root,name+".png"));}}
 static void Command(MainForm f,AppCommand cmd){Call(f,"ExecuteCommand",cmd);Pump(25);}static void Shortcut(MainForm f,Keys keys){if(keys==(Keys.Control|Keys.A)){var piano=(Control)Field(f,"_pianoRoll");var timeline=(Control)Field(f,"_timeline");Console.WriteLine("CTX visible="+piano.Visible+" piano="+piano.RectangleToScreen(piano.ClientRectangle)+" tracks="+timeline.RectangleToScreen(timeline.ClientRectangle)+" mouse="+Cursor.Position+" focus="+piano.ContainsFocus);}Check((bool)Call(f,"SendTestShortcut",keys),"Shortcut not handled: "+keys+" pianoContext="+Call(f,"PianoContext")+" text="+Call(f,"IsTextEntryFocused"));Pump(20);}
 static ProjectDocument Project(MainForm f){return (ProjectDocument)Field(f,"_project");}static void PointTo(Control c){c.Focus();Point point=c.PointToScreen(new Point(c.ClientSize.Width/2,c.ClientSize.Height/2));var form=c.FindForm() as MainForm;if(form!=null)Set(form,"_editorPointer",(Func<Point>)(()=>point));}
 [STAThread]static int Main(string[] args){root=Path.GetFullPath(args[0]);Directory.CreateDirectory(root);Environment.SetEnvironmentVariable("SLOPX_PROFILE",Path.Combine(root,"profile"));SetProcessDpiAwarenessContext((IntPtr)(-4));Application.SetUnhandledExceptionMode(UnhandledExceptionMode.CatchException);Application.ThreadException+=delegate(object s,ThreadExceptionEventArgs e){errors.Add(e.Exception);};Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);UiText.Load("en-US");var settings=new AppSettings{AudioBackend="WASAPI",InputEndpoint=WasapiStream.Devices(true).Where(d=>d.Name.Contains("Loopback Main")).Select(d=>d.Id).FirstOrDefault()??""};settings.Integration.QuickStart=false;var locale=LocaleCatalog.Load(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"locales","en-US.json"),"en-US");
 using(var form=new MainForm(settings,locale,false,null)){form.Show();Pump(300);var p=new ProjectDocument{Name="V8 Editor Verification",Tempo=120};var track=ProjectFactory.CreateTrack("Sampler Piano",TrackType.Midi);var region=ProjectFactory.CreateRegion("Four notes",0,16);foreach(var item in new[]{new[]{0,60},new[]{1,62},new[]{2,64},new[]{3,67}})region.Notes.Add(new MidiNote{StartBeat=item[0],Pitch=item[1],LengthBeats=.5,Velocity=90});track.Regions.Add(region);var other=ProjectFactory.CreateTrack("Second Track",TrackType.Midi);other.Regions.Add(ProjectFactory.CreateRegion("Second Region",0,4));p.Tracks.Add(track);p.Tracks.Add(other);Set(form,"_project",p);((ProjectHistory)Field(form,"_history")).Reset(true);Call(form,"Select",track.Id,region.Id);Call(form,"OpenEditor");Pump(60);var piano=(PianoRollEditor)Field(form,"_pianoRoll");var pc=(Control)Field(piano,"_canvas");var timeline=(TimelineEditor)Field(form,"_timeline");var tc=(Control)Field(timeline,"_canvas");((StudioScrollBar)Field(piano,"_vertical")).Value=55;((StudioScrollBar)Field(piano,"_horizontal")).Value=0;Pump(80);lines.Add("SETUP pianoVisible="+piano.Visible+" canvasVisible="+pc.Visible+" region="+Field(form,"_selectedRegionId")+" size="+pc.Size);
 Test("Pointer drag marquee selects multiple notes without creating a note",()=>{Drag(pc,70,27+10*14,55+1.8*48,27+13*14);Check(piano.SelectionCount==2,"Expected two selected notes, got "+piano.SelectionCount);Check(region.Notes.Count==4,"Marquee created notes");});
 Test("Shift-click extends selection; Ctrl-drag secondary Marquee works",()=>{Click(pc,55+2.2*48,27+8*14+5,Keys.Shift);Check(piano.SelectionCount==3,"Shift click did not extend");Drag(pc,70,27+10*14,55+1.8*48,27+13*14,Keys.Control);Check(piano.SelectionCount==2,"Ctrl marquee did not select two");});
 Test("Ctrl+A/C/V copies notes to the playhead; Cut and Undo operate on selected notes",()=>{PointTo(pc);Shortcut(form,Keys.Control|Keys.A);Check(piano.SelectionCount==4,"Ctrl+A not routed to piano");Shortcut(form,Keys.Control|Keys.C);Call(form,"SetCursorBeat",4.0);Shortcut(form,Keys.Control|Keys.V);Check(region.Notes.Count==8,"Piano paste expected 8 notes got "+region.Notes.Count);Check(piano.SelectionCount==4,"Pasted notes not selected");Shortcut(form,Keys.Control|Keys.X);Check(region.Notes.Count==4,"Cut did not remove group");Shortcut(form,Keys.Control|Keys.Z);Check(region.Notes.Count==8,"Undo did not restore group");});
 Test("Editor selection survives mixer refresh; arrows transpose notes without selecting tracks",()=>{PointTo(pc);Shortcut(form,Keys.Control|Keys.A);int selected=piano.SelectionCount;Call(form,"RefreshState");Check(piano.SelectionCount==selected,"Selection reset during mixer update");int low=region.Notes.Min(n=>n.Pitch);Shortcut(form,Keys.Up);Check(region.Notes.Min(n=>n.Pitch)==low+1,"Arrow did not transpose selected group");Check((Guid?)Field(form,"_selectedTrackId")==track.Id,"Arrow selected a different track");});
 Test("Ctrl+Up/Down change vertical editor zoom; Ctrl+Left/Right change horizontal zoom",()=>{PointTo(pc);int height=(int)Field(pc,"NoteHeight");Shortcut(form,Keys.Control|Keys.Up);Check((int)Field(pc,"NoteHeight")<height,"Piano vertical zoom out failed");Shortcut(form,Keys.Control|Keys.Down);Check((int)Field(pc,"NoteHeight")==height,"Piano vertical zoom in failed");int scale=settings.UiScale;Shortcut(form,Keys.Control|Keys.Right);Check(settings.UiScale==scale,"Editor zoom changed whole GUI");PointTo(tc);int lane=(int)Field(tc,"LaneHeight");Shortcut(form,Keys.Control|Keys.Up);Check((int)Field(tc,"LaneHeight")<lane,"Arrangement vertical zoom failed");Shortcut(form,Keys.Control|Keys.Down);});
 Test("Piano ruler drag seeks the shared transport without creating notes",()=>{PointTo(pc);int count=region.Notes.Count;int beatPixels=(int)Field(pc,"PixelsPerBeat");Drag(pc,55+beatPixels,12,55+beatPixels*2,12);Check(Math.Abs((double)Field(form,"_cursorBeat")-2)<.02,"Piano ruler did not move shared playhead");Check(region.Notes.Count==count,"Ruler drag created notes");});
 Test("Documented Alt-arrow transpose/nudge and Ctrl+R/Ctrl+T edit selected MIDI notes",()=>{PointTo(pc);Shortcut(form,Keys.Control|Keys.A);int low=region.Notes.Min(n=>n.Pitch);Shortcut(form,Keys.Alt|Keys.Up);Check(region.Notes.Min(n=>n.Pitch)==low+1,"Alt-Up transpose missing");Shortcut(form,Keys.Alt|Keys.Down);Check(region.Notes.Min(n=>n.Pitch)==low,"Alt-Down transpose missing");double start=region.Notes.Min(n=>n.StartBeat);Shortcut(form,Keys.Alt|Keys.Right);Check(region.Notes.Min(n=>n.StartBeat)>start,"Alt-Right nudge missing");Shortcut(form,Keys.Alt|Keys.Left);int count=region.Notes.Count;Shortcut(form,Keys.Control|Keys.R);Check(region.Notes.Count==count*2,"Ctrl-R did not repeat notes");Call(form,"SetCursorBeat",region.Notes.Skip(count).Min(n=>n.StartBeat)+.25);Shortcut(form,Keys.Control|Keys.T);Check(region.Notes.Count==count*2+1,"Ctrl-T did not split the selected crossing note");Shortcut(form,Keys.Control|Keys.Z);Shortcut(form,Keys.Control|Keys.Z);Check(region.Notes.Count==count,"Undo repeat/split mismatch");});
 Test("Ctrl+A follows hovered arrangement even while Piano Roll retains focus",()=>{PointTo(pc);int selected=piano.SelectionCount;Point hover=tc.PointToScreen(new Point(380,100));Set(form,"_editorPointer",(Func<Point>)(()=>hover));Check(pc.ContainsFocus,"Piano focus fixture missing");Shortcut(form,Keys.Control|Keys.A);Check(timeline.SelectedRegions.Count==2&&piano.SelectionCount==selected,"Hover context did not override focus");});
 Test("Ctrl+A follows mouse/editor context and multi-region Cut/Undo uses the common command",()=>{PointTo(tc);Shortcut(form,Keys.Control|Keys.A);Check(timeline.SelectedRegions.Count==2,"Arrangement Select All did not select 2 regions");Shortcut(form,Keys.Control|Keys.C);Shortcut(form,Keys.Control|Keys.X);Check(Project(form).Tracks.Sum(t=>t.Regions.Count)==0,"Cut did not remove regions");Shortcut(form,Keys.Control|Keys.Z);Check(Project(form).Tracks.Sum(t=>t.Regions.Count)==2,"Undo did not restore regions");});
 Test("Touch gesture infrastructure routes pinch to editor zoom and pan to viewport",()=>{DisplayScale.TouchMode=true;int before=timeline.Zoom;var screen=tc.PointToScreen(new Point(400,100));((ScaledCanvas)tc).ApplyNavigationGesture(3,screen,100,true);((ScaledCanvas)tc).ApplyNavigationGesture(3,screen,140,false);Check(timeline.Zoom>before,"Pinch did not zoom editor");timeline.ScrollHorizontalTo(12);double old=timeline.HorizontalBeat;((ScaledCanvas)tc).ApplyNavigationGesture(4,screen,0,true);((ScaledCanvas)tc).ApplyNavigationGesture(4,new Point(screen.X-100,screen.Y),0,false);Check(timeline.HorizontalBeat>old,"Two finger pan did not move viewport");DisplayScale.TouchMode=false;});
 Test("Global tracks reveal and chord progression emits preserved MIDI notes",()=>{Command(form,AppCommand.ShowGlobalTracks);var panel=(Control)Field(form,"_globalTracks");Check(panel.Height>80,"Global tracks did not open");var state=Project(form).Studio.Copy();state.Chords=ChordProgression.Parse("Fmaj7 | Am | C | G",4);Call(form,"CommitStudio","Test chords",state);var chords=ChordProgression.CreateTrack(state.Chords);Check(chords.Regions.Count==4&&chords.Regions.Sum(r=>r.Notes.Count)==13,"Chord MIDI not generated");string file=Path.Combine(root,"chords.slopdaw");ProjectFile.SaveAtomic(Project(form),file);Check(ProjectFile.Load(file).Studio.Chords.Count==4,"Chord progression lost on reload");Screenshot(form,"global-tracks");});
 Test("Green built-in instrument slot opens a real replacement popup on right-click",()=>{Call(form,"Select",track.Id,region.Id);Command(form,AppCommand.ToggleMixer);var mixer=Field(form,"_mixer");var strip=Find(form).OfType<ChannelStripControl>().First(c=>c.Track!=null&&c.Track.Id==track.Id);Pump(50);var rect=(Rectangle)Field(strip,"_instrument");Mouse(strip,0x204,rect.X+4,rect.Y+5,2);Mouse(strip,0x205,rect.X+4,rect.Y+5);Pump(50);var menu=Application.OpenForms.Cast<Form>().SelectMany(f=>Find(f)).OfType<ContextMenuStrip>().FirstOrDefault(m=>m.Visible);var actual=(ContextMenuStrip)Field(form,"_instrumentMenu");bool visible=actual!=null&&actual.Visible&&actual.Items.Count>=3;Check(visible,"Instrument replacement menu did not open");actual.Close();});
 Test("Native labels translate synchronously during pan/mix updates",()=>{Call(form,"ChangeLanguage","ja-JP");UiText.Apply(form);var inspector=Field(form,"_inspector");var header=(Control)Field(inspector,"_trackHeader");string expected=header.Text;for(int i=0;i<12;i++){Call(form,"ApplyTrackMix",track.Id,-12.0,i%2==0?-.5:.5,false,false);Check(header.Text==expected,"Japanese header changed during pan: "+header.Text);}var label=new Label{Text="Settings"};form.Controls.Add(label);UiText.Apply(label);label.Text="Cancel";Check(label.Text==UiText.Translate("Cancel"),"Native text was not translated synchronously");form.Controls.Remove(label);label.Dispose();Screenshot(form,"arrangement-mixer-ja");});
 Test("Key Commands uses a dark grid with legible foreground; input mode and animation persist",()=>{using(var prefs=new PreferencesForm(settings)){prefs.Show(form);Pump(80);var grid=Find(prefs).OfType<DataGridView>().Single();Check(grid.DefaultCellStyle.BackColor.GetBrightness()<.3,"Key grid cells remain white");Check(grid.DefaultCellStyle.ForeColor.GetBrightness()>.65,"Key grid text remains dark");var tab=Find(prefs).OfType<TabControl>().Single();tab.SelectedTab=grid.Parent as TabPage;Screenshot(prefs,"key-commands-ja");prefs.Close();}var s=new AppSettings{InputMode="Touchscreen",SmoothAnimation=false};string file=Path.Combine(root,"settings.json");SettingsStore.Save(s,file);var loaded=SettingsStore.Load(file);Check(loaded.InputMode=="Touchscreen"&&!loaded.SmoothAnimation,"Display/input preferences lost");});
 Test("GUI scaling preserves lane zoom, panel bounds and project content without UI errors",()=>{int lane=(int)Field(tc,"LaneHeight"),notes=Project(form).Tracks.Sum(t=>t.Regions.Sum(r=>r.Notes.Count));foreach(int scale in new[]{100,125,150,90,100}){settings.UiScale=scale;Call(form,"ApplyUiScale");Pump(35);Check((int)Field(tc,"LaneHeight")==lane,"Whole UI scale reset vertical editor zoom");Check(timeline.Width>250&&timeline.Height>120,"Scaled editing surface clipped");}Check(Project(form).Tracks.Sum(t=>t.Regions.Sum(r=>r.Notes.Count))==notes,"GUI scaling altered project");Screenshot(form,"scale100");});
 Test("Stock Ducker and Equalizer render original rotary interfaces with live parameter binding",()=>{var stock=StockEffects.Create(track.Id,"EDM Ducker");using(var editor=new StockEffectEditor(stock,changed=>stock=changed,()=>new StockEffectProcessor())){editor.Show(form);Pump(80);var knobs=Find(editor).OfType<EffectKnob>().ToList();Check(knobs.Count==6,"Ducker knob count");var knob=knobs.First(k=>k.Parameter.Key=="Depth");var numeric=knob.Parent.Controls.OfType<NumericUpDown>().Single();numeric.Value=35;Check(Math.Abs(stock.Value("Depth",0)-35)<.01,"Ducker parameter not bound");Screenshot(editor,"ducker");editor.Close();}using(var eq=new StockEffectEditor(StockEffects.Create(track.Id,"Visual Equalizer"),s=>{},()=>null)){eq.Show(form);Pump(80);Check(Find(eq).OfType<EffectKnob>().Count()==15,"EQ rotary controls missing");Screenshot(eq,"equalizer");eq.Close();}});
 Test("Sampler slot opens a real PCM waveform/mapping editor; preset changes update track engine state",()=>{var current=Project(form).Tracks.First(t=>t.Type==TrackType.Midi);Call(form,"OpenSampler",current);Pump(90);var editor=Application.OpenForms.OfType<SamplerEditor>().Single();var choice=(StudioChoice)Field(editor,"_preset");choice.SelectedItem="Pluck";Pump(60);Check(Project(form).Tracks.First(t=>t.Id==current.Id).Instrument=="Pluck","Sampler preset change not committed");Screenshot(editor,"sampler");editor.Close();});
 if(args.Length>1)Test("MP4 GUI import extracts real audio, opens synchronized preview and seeks with transport",()=>{Call(form,"ImportMovie",Path.Combine(args[1],"fixture.mp4"));var timeout=Stopwatch.StartNew();while((bool)Field(form,"_importing")&&timeout.ElapsedMilliseconds<15000)Pump(30);Check(!(bool)Field(form,"_importing"),"Movie import did not finish");Check(Project(form).Studio.Video!=null,"Movie not linked to project");Check(Project(form).Tracks.Any(t=>t.Type==TrackType.Audio&&t.Regions.Any(r=>File.Exists(r.MediaPath))),"Movie audio not extracted");var movie=(VideoPreviewForm)Field(form,"_videoWindow");Check(movie!=null&&movie.Visible,"Movie window not shown");Call(form,"SetCursorBeat",Project(form).Studio.Video.StartBeat+1.0);Pump(900);var picture=(PictureBox)Field(movie,"_picture");Check(picture.Image!=null,"Movie preview did not decode frame");Screenshot(movie,"movie-preview");movie.Close();});
 Test("Actual sample arrangement, selected piano roll, chord lanes and quick start render at desktop size",()=>{((ProjectHistory)Field(form,"_history")).Reset(true);Call(form,"OpenProjectPath",Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"Examples","EDM Sample - Melodic House.slopdaw"));Pump(100);var split=(SplitContainer)Field(form,"_workspaceSplit");var lower=Field(form,"_lowerDock");Call(lower,"ShowMixer");split.Panel2Collapsed=false;((Control)Field(form,"_globalTracks")).Height=8;timeline.SetLaneHeight(40);timeline.SetZoom(12);timeline.ScrollHorizontalTo(80);Call(form,"SetCursorBeat",96.0);Command(form,AppCommand.PlayOrStop);Pump(250);Screenshot(form,"melodic-house");Command(form,AppCommand.Stop);var lead=Project(form).Tracks[4];var clip=lead.Regions.First();Call(form,"Select",lead.Id,clip.Id);Call(form,"OpenEditor");PointTo(pc);Shortcut(form,Keys.Control|Keys.A);Screenshot(form,"piano-roll-selection");Command(form,AppCommand.ShowGlobalTracks);Screenshot(form,"chords-and-global");using(var quick=new QuickStartForm(new List<RecoveryItem>(),null)){quick.Show(form);Pump(60);Screenshot(quick,"quick-start");quick.Close();}});
 Test("Help MIT Licences viewer displays the full legal text unchanged",()=>{bool shown=false;var timer=new System.Windows.Forms.Timer{Interval=80};timer.Tick+=delegate{var viewer=Application.OpenForms.Cast<Form>().FirstOrDefault(f=>f.Text.Contains("MIT"));if(viewer==null)return;var text=Find(viewer).OfType<RichTextBox>().Single();Check(text.Text.Contains("Permission is hereby granted, free of charge")&&text.Text.Contains("IN NO EVENT"),"MIT viewer truncated legal text");shown=true;Screenshot(viewer,"mit-licences");timer.Stop();viewer.Close();};timer.Start();Command(form,AppCommand.MitLicences);timer.Dispose();Check(shown,"MIT viewer was not displayed");});
 ((ProjectHistory)Field(form,"_history")).Reset(true);Set(form,"_closing",true);form.Close();}
 lines.Add("NOT RUN physical touch tablet gestures, mixed-monitor DPI, physical MIDI keyboard, full reference application visual/command parity.");File.WriteAllLines(Path.Combine(root,"gui.txt"),lines);Console.WriteLine(String.Join(Environment.NewLine,lines.ToArray()));return failures==0?0:1;
