 static IEnumerable<Control> Find(Control root){foreach(Control c in root.Controls){yield return c;foreach(var nested in Find(c))yield return nested;}}
 static IEnumerable<ContextMenuStrip> FindMenus(){var field=typeof(ToolStripManager).GetField("toolStrips",BindingFlags.NonPublic|BindingFlags.Static);if(field!=null){var enumerable=field.GetValue(null) as System.Collections.IEnumerable;if(enumerable!=null)foreach(var item in enumerable){var weak=item as WeakReference;var strip=(weak==null?item:weak.Target) as ContextMenuStrip;if(strip!=null)yield return strip;}}}
